        let mut m = op_map_empty();
        for &(k, v) in &[(1i64, 10i64), (2, 20)] {
            m = minsert_int(m, k, v);
        }
        m = mremove_int(m, 999); // absent
        assert_eq!(op_map_size(m), 2);
        assert_eq!(mlookup_int(m, 1), Some(10));
